"""Tests for bulk discount rule."""

from decimal import Decimal

import pytest

from pricing import LineItem
from pricing.bulk_discount import (
    BULK_DISCOUNT_PERCENT,
    BULK_QUANTITY_THRESHOLD,
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)


class TestBulkDiscountThreshold:
    """Tests for the bulk discount quantity threshold (Req 1.1, 1.2, 1.3)."""

    @pytest.mark.l4("C-8764baca")
    def test_quantity_exactly_10_qualifies_for_bulk_discount(self):
        """WHEN a line item has a quantity of exactly 10 THEN it qualifies."""
        item = LineItem("widget", Decimal("10.00"), 10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_above_10_qualifies_for_bulk_discount(self):
        """WHEN a line item has a quantity greater than 10 THEN it qualifies."""
        item = LineItem("widget", Decimal("10.00"), 11)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-4284227d")
    def test_quantity_9_does_not_qualify_for_bulk_discount(self):
        """WHEN a line item has a quantity of 9 THEN it does not qualify."""
        item = LineItem("widget", Decimal("10.00"), 9)
        assert qualifies_for_bulk_discount(item) is False


class TestBulkDiscountCalculation:
    """Tests for the bulk discount calculation (Req 1.1, 1.2, 1.3, 1.4)."""

    @pytest.mark.l4("C-8764baca")
    def test_calculate_discount_for_quantity_exactly_10(self):
        """WHEN quantity is exactly 10 THEN the system applies a 5% discount."""
        item = LineItem("widget", Decimal("10.00"), 10)
        discount = calculate_bulk_discount(item)
        # 10 units at $10.00 each = $100.00, 5% = $5.00
        assert discount == Decimal("5.00")

    @pytest.mark.l4("C-e4015f6b")
    def test_calculate_discount_for_quantity_above_10(self):
        """WHEN quantity is greater than 10 THEN the system applies a 5% discount."""
        item = LineItem("widget", Decimal("10.00"), 15)
        discount = calculate_bulk_discount(item)
        # 15 units at $10.00 each = $150.00, 5% = $7.50
        assert discount == Decimal("7.50")

    @pytest.mark.l4("C-4284227d")
    def test_calculate_discount_for_quantity_below_threshold(self):
        """WHEN quantity is 9 or fewer THEN no bulk discount is applied."""
        item = LineItem("widget", Decimal("10.00"), 9)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_rounds_half_up_to_cents(self):
        """WHEN calculating the bulk discount THEN round to 0.01 using half-up."""
        # Use a price that results in a discount needing rounding
        # $1.00 * 10 = $10.00, 5% = $0.50 (no rounding needed)
        # Use $1.23 * 10 = $12.30, 5% = $0.615 -> $0.62 (half-up)
        item = LineItem("widget", Decimal("1.23"), 10)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.62")


class TestBulkDiscountConstants:
    """Tests for the bulk discount constants."""

    def test_bulk_quantity_threshold_is_10(self):
        """The threshold for bulk discount eligibility is 10 units."""
        assert BULK_QUANTITY_THRESHOLD == 10

    def test_bulk_discount_percent_is_5(self):
        """The bulk discount percentage is 5%."""
        assert BULK_DISCOUNT_PERCENT == Decimal("5")

